// SQLite connection for local development (Review & Approval Workflow, Dev 3).
//
// This is scoped to the Review Workflow feature specifically â€” it is not the
// team's shared database connection. See config/db.js for that placeholder.
//
// Opens the same server/database/hrckmp.db file as config/sqliteDb.js (Dev 2)
// and (re-)applies the shared database/schema.sql, which is idempotent â€”
// every statement is CREATE ... IF NOT EXISTS â€” so either feature's config
// module can run it safely regardless of which one starts first. Seeds a
// handful of sample review requests, targeting the seeded work permits, only
// when the table is empty.

const path = require('path');
const fs = require('fs');
const Database = require('better-sqlite3');
const env = require('./env');

const DATABASE_DIR = path.join(__dirname, '..', '..', 'database');
const DB_PATH = env.sqliteDbPath || path.join(DATABASE_DIR, 'hrckmp.db');
const SCHEMA_PATH = path.join(DATABASE_DIR, 'schema.sql');

if (!fs.existsSync(DATABASE_DIR)) {
  fs.mkdirSync(DATABASE_DIR, { recursive: true });
}

const db = new Database(DB_PATH);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

db.exec(fs.readFileSync(SCHEMA_PATH, 'utf8'));

const SEED_REVIEWS = [
  {
    target_type: 'work_permit',
    target_id: 1,
    title: 'Review: Singapore Employment Pass copy',
    review_status: 'APPROVED',
  },
  {
    target_type: 'work_permit',
    target_id: 2,
    title: 'Review: Singapore S Pass eligibility wording',
    review_status: 'IN_REVIEW',
  },
  {
    target_type: 'work_permit',
    target_id: 3,
    title: 'Review: Philippines AEP fee update',
    review_status: 'PENDING',
  },
  {
    target_type: 'work_permit',
    target_id: 4,
    title: 'Review: Malaysia Employment Pass criteria',
    review_status: 'CHANGES_REQUESTED',
  },
  {
    target_type: 'work_permit',
    target_id: 5,
    title: 'Review: Vietnam Work Permit (superseded) retirement',
    review_status: 'REJECTED',
  },
];

function seedIfEmpty() {
  const { count } = db.prepare('SELECT COUNT(*) AS count FROM review_requests').get();
  if (count > 0) return;

  const now = new Date().toISOString();
  const insert = db.prepare(`
    INSERT INTO review_requests (
      target_type, target_id, title, review_status, created_at, updated_at
    ) VALUES (
      @target_type, @target_id, @title, @review_status, @created_at, @updated_at
    )
  `);

  const insertAll = db.transaction((rows) => {
    rows.forEach((row) => insert.run({ ...row, created_at: now, updated_at: now }));
  });
  insertAll(SEED_REVIEWS);
}

seedIfEmpty();

module.exports = db;
// Dev 3 â€” parameterized SQL data access for review_requests (SQLite).
// review_comments / notifications data access are Phase 3 (state machine,
// comments, notifications) and not implemented yet.

const db = require('../config/reviewSqliteDb');

function findAll({ search, targetType, status } = {}) {
  let sql = 'SELECT * FROM review_requests WHERE 1 = 1';
  const params = [];

  if (targetType) {
    sql += ' AND target_type = ?';
    params.push(targetType);
  }
  if (status) {
    sql += ' AND review_status = ?';
    params.push(status);
  }
  if (search) {
    sql += ' AND title LIKE ?';
    params.push(`%${search}%`);
  }
  sql += ' ORDER BY created_at DESC';

  return db.prepare(sql).all(...params);
}

function findById(id) {
  return db.prepare('SELECT * FROM review_requests WHERE request_id = ?').get(id) || null;
}

function insert(row) {
  const stmt = db.prepare(`
    INSERT INTO review_requests (
      target_type, target_id, title, review_status, created_at, updated_at
    ) VALUES (
      @target_type, @target_id, @title, @review_status, @created_at, @updated_at
    )
  `);
  const info = stmt.run(row);
  return findById(info.lastInsertRowid);
}

function update(id, row) {
  const stmt = db.prepare(`
    UPDATE review_requests SET
      target_type = @target_type,
      target_id = @target_id,
      title = @title,
      review_status = @review_status,
      updated_at = @updated_at
    WHERE request_id = @request_id
  `);
  stmt.run({ ...row, request_id: id });
  return findById(id);
}

function archive(id, updatedAt) {
  db.prepare('UPDATE review_requests SET review_status = ?, updated_at = ? WHERE request_id = ?').run(
    'ARCHIVED',
    updatedAt,
    id
  );
  return findById(id);
}

module.exports = { findAll, findById, insert, update, archive };
// Dev 3 â€” review_requests CRUD business logic (Section 11).
// Maps between the frontend's camelCase review shape and the SQLite
// snake_case columns so reviewRoutes/reviewController stay simple.
// The full state machine, comments, notifications, and publish action
// (Section 14.4) are Phase 3 enhancements and not implemented yet â€” this is
// basic CRUD only (Phase 2).

const reviewRepository = require('../repositories/reviewRepository');

const VALID_TARGET_TYPES = ['compliance_record', 'work_permit'];
const VALID_REVIEW_STATUSES = [
  'PENDING',
  'IN_REVIEW',
  'APPROVED',
  'CHANGES_REQUESTED',
  'REJECTED',
  'ARCHIVED',
];

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.status = 400;
  }
}

function toDbRow(data) {
  if (!data.title || !data.title.trim()) {
    throw new ValidationError('Title is required');
  }
  if (!VALID_TARGET_TYPES.includes(data.targetType)) {
    throw new ValidationError('A valid target type is required');
  }
  const targetId = Number(data.targetId);
  if (!Number.isInteger(targetId) || targetId <= 0) {
    throw new ValidationError('A valid target id is required');
  }

  return {
    target_type: data.targetType,
    target_id: targetId,
    title: data.title,
    review_status: VALID_REVIEW_STATUSES.includes(data.reviewStatus) ? data.reviewStatus : 'PENDING',
  };
}

function toApiShape(row) {
  if (!row) return null;
  return {
    id: row.request_id,
    targetType: row.target_type,
    targetId: row.target_id,
    title: row.title,
    reviewStatus: row.review_status,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function listReviews(filters) {
  return reviewRepository.findAll(filters).map(toApiShape);
}

function getReviewById(id) {
  return toApiShape(reviewRepository.findById(id));
}

function createReview(data) {
  const now = new Date().toISOString();
  const row = { ...toDbRow(data), created_at: now, updated_at: now };
  return toApiShape(reviewRepository.insert(row));
}

function updateReview(id, data) {
  const existing = reviewRepository.findById(id);
  if (!existing) return null;
  const now = new Date().toISOString();
  const row = { ...toDbRow(data), updated_at: now };
  return toApiShape(reviewRepository.update(id, row));
}

function archiveReview(id) {
  const existing = reviewRepository.findById(id);
  if (!existing) return null;
  const now = new Date().toISOString();
  return toApiShape(reviewRepository.archive(id, now));
}

module.exports = {
  ValidationError,
  listReviews,
  getReviewById,
  createReview,
  updateReview,
  archiveReview,
};
// Dev 3 â€” review_requests request handlers (mirrors reviewRoutes.js)

const reviewWorkflowService = require('../services/reviewWorkflowService');

function parseId(req, res) {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    res.status(400).json({ message: 'Invalid review request id' });
    return null;
  }
  return id;
}

function list(req, res, next) {
  try {
    const { search, targetType, status } = req.query;
    const reviews = reviewWorkflowService.listReviews({ search, targetType, status });
    res.json(reviews);
  } catch (err) {
    next(err);
  }
}

function getById(req, res, next) {
  try {
    const id = parseId(req, res);
    if (id === null) return;
    const review = reviewWorkflowService.getReviewById(id);
    if (!review) {
      res.status(404).json({ message: 'Review request not found' });
      return;
    }
    res.json(review);
  } catch (err) {
    next(err);
  }
}

function create(req, res, next) {
  try {
    const review = reviewWorkflowService.createReview(req.body || {});
    res.status(201).json(review);
  } catch (err) {
    next(err);
  }
}

function update(req, res, next) {
  try {
    const id = parseId(req, res);
    if (id === null) return;
    const review = reviewWorkflowService.updateReview(id, req.body || {});
    if (!review) {
      res.status(404).json({ message: 'Review request not found' });
      return;
    }
    res.json(review);
  } catch (err) {
    next(err);
  }
}

function archive(req, res, next) {
  try {
    const id = parseId(req, res);
    if (id === null) return;
    const review = reviewWorkflowService.archiveReview(id);
    if (!review) {
      res.status(404).json({ message: 'Review request not found' });
      return;
    }
    res.json(review);
  } catch (err) {
    next(err);
  }
}

module.exports = { list, getById, create, update, archive };
const express = require('express');
const reviewController = require('../controllers/reviewController');

const router = express.Router();

// Dev 3 â€” review_requests CRUD (Section 14.4). Transitions, publish,
// comments, and notifications are out of scope for this basic CRUD pass.
router.get('/', reviewController.list);
router.get('/:id', reviewController.getById);
router.post('/', reviewController.create);
router.put('/:id', reviewController.update);
router.patch('/:id/archive', reviewController.archive);

module.exports = router;
