import { useEffect, useState } from 'react';
import { Formik, Form } from 'formik';
import { Box, TextField, MenuItem, Button, Stack, Paper, Typography, Divider } from '@mui/material';
import { reviewValidationSchema } from './reviewValidation';
import {
  TARGET_TYPES,
  TARGET_TYPE_LABELS,
  EDITABLE_REVIEW_STATUSES,
  REVIEW_STATUS_LABELS,
} from '../../utils/enums';
import permitService from '../../api/permitService';

const gridSx = {
  display: 'grid',
  gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
  gap: 2,
};

function FormSection({ title, description, children }) {
  return (
    <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
      <Typography variant="subtitle1" fontWeight={600}>
        {title}
      </Typography>
      {description && (
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {description}
        </Typography>
      )}
