}

// Picks the record being reviewed. Work permits have real data to choose
// from, so that target type gets a proper dropdown of permits by name.
// Compliance records (Dev 1) aren't built yet, so that option falls back to
// a plain ID field until that feature exists.
function TargetField({ targetType, value, onChange, onBlur, error, helperText }) {
  const [permits, setPermits] = useState([]);
  const [loadingPermits, setLoadingPermits] = useState(targetType === 'work_permit');

  useEffect(() => {
    if (targetType !== 'work_permit') return;
    setLoadingPermits(true);
    permitService.list().then((data) => {
      setPermits(data);
      setLoadingPermits(false);
    });
  }, [targetType]);

  if (targetType === 'work_permit') {
    return (
      <TextField
        select
        label="Work Permit"
        name="targetId"
        value={permits.some((p) => String(p.id) === String(value)) ? value : ''}
        onChange={onChange}
        onBlur={onBlur}
        error={error}
        helperText={helperText || (loadingPermits ? 'Loading permitsâ€¦' : 'Select the permit being reviewed')}
        disabled={loadingPermits}
        fullWidth
      >
        {permits.map((p) => (
          <MenuItem key={p.id} value={p.id}>
            {p.title} ({p.permitType})
          </MenuItem>
        ))}
      </TextField>
    );
  }

  return (
    <TextField
      type="number"
      label="Compliance Record ID"
      name="targetId"
      value={value}
      onChange={onChange}
      onBlur={onBlur}
      error={error}
      helperText={
        helperText ||
        "Compliance Content Management isn't built yet â€” enter the record ID manually for now."
      }
      fullWidth
    />
  );
}

export default function ReviewForm({ initialValues, onSubmit, onCancel, submitLabel = 'Save', isEdit = false }) {
  return (
    <Formik
      initialValues={initialValues}
      validationSchema={reviewValidationSchema}
      enableReinitialize
      onSubmit={onSubmit}
    >
      {({ values, errors, touched, handleChange, handleBlur, setFieldValue, isSubmitting }) => (
        <Form noValidate>
          <FormSection
            title="Basic Information"
            description="What is being reviewed, and which record or permit it targets."
          >
            <TextField
              label="Title"
              name="title"
              placeholder="e.g. Review: Singapore Employment Pass copy"
              value={values.title}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.title && Boolean(errors.title)}
              helperText={touched.title && errors.title}
              fullWidth
              sx={{ gridColumn: { sm: '1 / span 2' } }}
            />

            <TextField
              select
              label="Target Type"
              name="targetType"
              value={values.targetType}
              onChange={(e) => {
                setFieldValue('targetType', e.target.value);
                setFieldValue('targetId', '');
              }}
              onBlur={handleBlur}
              error={touched.targetType && Boolean(errors.targetType)}
              helperText={touched.targetType && errors.targetType}
              fullWidth
            >
              {TARGET_TYPES.map((t) => (
                <MenuItem key={t} value={t}>
                  {TARGET_TYPE_LABELS[t]}
                </MenuItem>
              ))}
            </TextField>

            <TargetField
              targetType={values.targetType}
              value={values.targetId}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.targetId && Boolean(errors.targetId)}
              helperText={touched.targetId && errors.targetId}
            />
          </FormSection>

          {isEdit && (
            <FormSection title="Review Status" description="Current stage of this review request.">
              <TextField
                select
                label="Review Status"
                name="reviewStatus"
                value={values.reviewStatus}
                onChange={handleChange}
                onBlur={handleBlur}
                error={touched.reviewStatus && Boolean(errors.reviewStatus)}
                helperText={
                  (touched.reviewStatus && errors.reviewStatus) ||
                  'Use the Archive action on the request to set Archived'
                }
                fullWidth
              >
                {EDITABLE_REVIEW_STATUSES.map((s) => (
                  <MenuItem key={s} value={s}>
                    {REVIEW_STATUS_LABELS[s]}
                  </MenuItem>
                ))}
              </TextField>
            </FormSection>
          )}

          <Stack direction="row" spacing={2} justifyContent="flex-end">
            <Button onClick={onCancel} disabled={isSubmitting}>
              Cancel
            </Button>
            <Button type="submit" variant="contained" disabled={isSubmitting}>
              {submitLabel}
            </Button>
          </Stack>
        </Form>
      )}
    </Formik>
  );
}
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Box, Typography, Alert } from '@mui/material';
import PageHeader from '../../components/common/PageHeader';
import AppBreadcrumbs from '../../components/common/AppBreadcrumbs';
import ReviewForm from './ReviewForm';
import reviewService from '../../api/reviewService';
import { emptyReview } from './reviewValidation';

export default function ReviewFormPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = Boolean(id);
  const [initialValues, setInitialValues] = useState(isEdit ? null : emptyReview);
  const [notFound, setNotFound] = useState(false);
  const [submitError, setSubmitError] = useState('');

  useEffect(() => {
    if (!isEdit) return;
    reviewService.getById(id).then((review) => {
      if (!review) {
        setNotFound(true);
        return;
      }
      setInitialValues({ ...emptyReview, ...review });
    });
  }, [id, isEdit]);

  const handleSubmit = (values, { setSubmitting }) => {
    setSubmitError('');
    const action = isEdit ? reviewService.update(id, values) : reviewService.create(values);
    action
      .then((review) => {
        navigate(`/reviews/${review.id}`);
      })
      .catch((err) => {
        setSubmitError(err.response?.data?.message || 'Something went wrong. Please try again.');
        setSubmitting(false);
      });
  };

  if (notFound) {
    return <Typography>Review request not found.</Typography>;
  }

  if (!initialValues) {
    return <Typography>Loadingâ€¦</Typography>;
  }

  return (
    <Box>
      <AppBreadcrumbs
        items={[
          { label: 'Dashboard', href: '/' },
          { label: 'Review & Approval', href: '/reviews' },
          { label: isEdit ? 'Edit Review Request' : 'New Review Request' },
        ]}
      />
      <PageHeader
        title={isEdit ? 'Edit Review Request' : 'New Review Request'}
        subtitle={
          isEdit
            ? 'Update the details of this review request.'
            : 'Submit a new review request against a compliance record or work permit.'
        }
      />
      {submitError && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setSubmitError('')}>
          {submitError}
        </Alert>
      )}
      <ReviewForm
        initialValues={initialValues}
        onSubmit={handleSubmit}
        onCancel={() => navigate(isEdit ? `/reviews/${id}` : '/reviews')}
        submitLabel={isEdit ? 'Save Changes' : 'Create Review Request'}
        isEdit={isEdit}
      />
    </Box>
  );
}
import * as Yup from 'yup';
