// Dev 2 â€” parameterized SQL data access for work_permits (SQLite).

const db = require('../config/sqliteDb');

function findAll({ search, country, status } = {}) {
  let sql = 'SELECT * FROM work_permits WHERE 1 = 1';
  const params = [];

  if (country) {
    sql += ' AND country_code = ?';
    params.push(country);
  }
  if (status) {
    sql += ' AND status = ?';
    params.push(status);
  }
  if (search) {
    sql += ' AND (title LIKE ? OR permit_type LIKE ?)';
    const like = `%${search}%`;
    params.push(like, like);
  }
  sql += ' ORDER BY title ASC';

  return db.prepare(sql).all(...params);
}

function findById(id) {
  return db.prepare('SELECT * FROM work_permits WHERE permit_id = ?').get(id) || null;
}

function insert(row) {
  const stmt = db.prepare(`
    INSERT INTO work_permits (
      country_code, permit_type, title, description, eligibility_criteria,
      processing_time_days, validity_months, government_fee, currency_code,
      worker_type, visibility, source_url, version, status, created_at, updated_at
    ) VALUES (
      @country_code, @permit_type, @title, @description, @eligibility_criteria,
      @processing_time_days, @validity_months, @government_fee, @currency_code,
      @worker_type, @visibility, @source_url, @version, @status, @created_at, @updated_at
    )
  `);
  const info = stmt.run(row);
  return findById(info.lastInsertRowid);
}

function update(id, row) {
  const stmt = db.prepare(`
    UPDATE work_permits SET
      country_code = @country_code,
      permit_type = @permit_type,
      title = @title,
      description = @description,
      eligibility_criteria = @eligibility_criteria,
      processing_time_days = @processing_time_days,
      validity_months = @validity_months,
      government_fee = @government_fee,
      currency_code = @currency_code,
      worker_type = @worker_type,
      visibility = @visibility,
      source_url = @source_url,
      version = @version,
      status = @status,
      updated_at = @updated_at
    WHERE permit_id = @permit_id
  `);
  stmt.run({ ...row, permit_id: id });
  return findById(id);
}

function archive(id, updatedAt) {
  db.prepare('UPDATE work_permits SET status = ?, updated_at = ? WHERE permit_id = ?').run(
    'ARCHIVED',
    updatedAt,
    id
  );
  return findById(id);
}

module.exports = { findAll, findById, insert, update, archive };
// Dev 2 â€” work_permits CRUD business logic (Section 11).
// Maps between the frontend's camelCase permit shape and the SQLite
// snake_case columns so permitRoutes/permitController stay simple.

const permitRepository = require('../repositories/permitRepository');

const VALID_STATUSES = ['DRAFT', 'PUBLISHED', 'ARCHIVED'];
const VALID_WORKER_TYPES = ['LOCAL', 'FOREIGN_WORKER', 'EXPATRIATE', 'ALL_EMPLOYEES'];
const VALID_VISIBILITY = ['COMPLIANCE_ONLY', 'INTERNAL_STAFF', 'CLIENT_SHAREABLE'];

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.status = 400;
  }
}

function toNullableNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  const num = Number(value);
  return Number.isNaN(num) ? null : num;
}

function toDbRow(data) {
  if (!data.title || !data.title.trim()) {
    throw new ValidationError('Title is required');
  }
  if (!data.permitType || !data.permitType.trim()) {
    throw new ValidationError('Permit type is required');
  }
  if (!data.countryCode) {
    throw new ValidationError('Country is required');
  }

  return {
    country_code: data.countryCode,
    permit_type: data.permitType,
    title: data.title,
    description: data.description || null,
    eligibility_criteria: data.eligibilityCriteria || null,
    processing_time_days: toNullableNumber(data.processingTimeDays),
    validity_months: toNullableNumber(data.validityMonths),
    government_fee: toNullableNumber(data.governmentFee),
    currency_code: data.currencyCode || null,
    worker_type: VALID_WORKER_TYPES.includes(data.workerType) ? data.workerType : 'FOREIGN_WORKER',
    visibility: VALID_VISIBILITY.includes(data.visibility) ? data.visibility : 'INTERNAL_STAFF',
    source_url: data.sourceUrl || null,
    version: data.version || 1,
    status: VALID_STATUSES.includes(data.status) ? data.status : 'DRAFT',
  };
}

function toApiShape(row) {
  if (!row) return null;
  return {
    id: row.permit_id,
    countryCode: row.country_code,
    permitType: row.permit_type,
    title: row.title,
    description: row.description || '',
    eligibilityCriteria: row.eligibility_criteria || '',
    processingTimeDays: row.processing_time_days,
    validityMonths: row.validity_months,
    governmentFee: row.government_fee,
    currencyCode: row.currency_code || '',
    workerType: row.worker_type,
    visibility: row.visibility,
    sourceUrl: row.source_url || '',
    version: row.version,
    status: row.status,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function listPermits(filters) {
  return permitRepository.findAll(filters).map(toApiShape);
